/* @lc app=leetcode id=999 lang=kotlin */ class Solution { fun numRookCaptures(board: Array<CharArray>): Int = (0 until 64).first { board[it / 8][it % 8] == 'R' }.let { k -> listOf(1 to 0, -1 to 0, 0 to 1, 0 to -1).count { (dx, dy) -> (1..7).map { t -> k / 8 + t * dx to k % 8 + t * dy }.takeWhile { (r, c) -> r in 0..7 && c in 0..7 }.map { (r, c) -> board[r][c] }.firstOrNull { it != '.' } == 'p' } } }